-- Loads the active theme generated by dots-apply-theme.
-- If it does not exist yet (for example, right after cloning the repo),
-- falls back to Catppuccin green so Hyprland still starts.

local defaults = {
    name      = "catppuccin/green (default)",
    border    = "a6e3a1",
    shadow    = "a6e3a1",
    wallpaper = "",
    cursor    = "hypr-dots-green",
}

local config_home = os.getenv("XDG_CONFIG_HOME") or (os.getenv("HOME") .. "/.config")
local ok, theme = pcall(dofile, config_home .. "/hypr/current-theme.lua")

if not ok or type(theme) ~= "table" then
    return defaults
end

for key, value in pairs(defaults) do
    if theme[key] == nil then theme[key] = value end
end
return theme
